// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address caller, uint256 kink) public {
        vm.assume(kink > 0 && kink < type(uint256).max);

        uint256 validKink = kink % 1e27;
        if (validKink == 0) {
            validKink = 1;
        }

        bytes4 sig = bytes4(keccak256("setSlopes(address,(uint256,uint256,uint256))"));
        address asset = address(0x123);

        bytes memory slopesEncoded = abi.encode(validKink, uint256(0), uint256(0));
        bytes memory data = abi.encodePacked(sig, abi.encode(asset, slopesEncoded));

        bool ok;
        vm.prank(caller);
        (bool success, ) = address(c).call(data);
        ok = success;

        assertTrue(!ok);
    }
}
